INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch12$PT128-S2-Q23$batch12$, 128, 2, 23, $batch12$Parallel$batch12$, $batch12$Some people believe there is intelligent life somewhere in the universe besides Earth. But no one who believes that could also believe all planets other than Earth are devoid of life. Thus, some people do not believe all planets other than Earth are devoid of life.$batch12$, $batch12$The reasoning in which one of the following is most similar to the reasoning in the argument above?$batch12$, $batch12$C$batch12$, true, $batch12$Batch 12; question text from local bank.$batch12$ FROM lr_sections s WHERE s.preptest=128 AND s.section=2 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT128-S2-Q23$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$A$batch12$, $batch12$Some people believe computers are capable of thought. Since no one who does not believe computer chess programs sometimes beat human chess masters believes computers can think, it follows that computer chess programs do sometimes beat human chess masters.$batch12$, $batch12$Bad Conclusion Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT128-S2-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$A$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$B$batch12$, $batch12$Some cat owners believe cats are incapable of feeling guilty. Since one could think that an animal is capable of feeling guilty only if one thought the animal had a conception of morality, it follows that some cat owners do not believe cats have a conception of morality.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT128-S2-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$B$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$C$batch12$, $batch12$Some dog owners believe their dogs are emotionally attached to them. Since no one could believe that and also believe dogs are incapable of thought, it follows that some dog owners do not believe dogs are incapable of thought.$batch12$, $batch12$Correct$batch12$, true FROM lr_questions q WHERE q.qid=$batch12$PT128-S2-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$C$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$D$batch12$, $batch12$Some people believe humans will someday colonize other planets. Since anyone who believes that probably also believes overpopulation of Earth is not a problem, it follows that some people do not believe overpopulation of Earth is not a problem.$batch12$, $batch12$Bad Premise Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT128-S2-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$D$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch12$E$batch12$, $batch12$Some people believe there is life on planets other than Earth. Since anyone who believes that must also believe other planets have atmospheres that can support life, it follows that other planets do have atmospheres that can support life.$batch12$, $batch12$Bad Conclusion Match$batch12$, false FROM lr_questions q WHERE q.qid=$batch12$PT128-S2-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch12$E$batch12$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT128-S2-Q23$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$Some people don't believe all other planets are lifeless.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$Some people believe there's intelligent life elsewhere. No one who believes that could also believe all other planets are lifeless.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$Recipe: Some people believe X. No one who believes X believes Y. So some people don't believe Y. Valid.$batch12$), (3, $batch12$Goal$batch12$, $batch12$Some believe X; no X-believer believes Y; so some don't believe Y.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT128-S2-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This concludes chess programs do win, a claim about the world, not about belief.$batch12$), ($batch12$B$batch12$, $batch12$The rule ties believing animals can feel guilt to believing they have morality. These owners believe cats can't feel guilt, so the rule never kicks in.$batch12$), ($batch12$C$batch12$, $batch12$Some owners believe their dogs are attached to them. No one could believe that and believe dogs can't think. So some owners don't believe dogs can't think. Same recipe.$batch12$), ($batch12$D$batch12$, $batch12$"Probably also believes" is weaker than "no one could."$batch12$), ($batch12$E$batch12$, $batch12$This concludes a fact about planets, not about beliefs.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT128-S2-Q23$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
